class Producto:
    def __init__(self, id, nombre, precio, costo, stock=0):
        self.id = id
        self.nombre = nombre
        self.costo = costo
        self.precio = precio      # pasa por el setter: se valida al nacer
        self._stock = stock

    @property
    def precio(self):
        return self._precio

    @precio.setter
    def precio(self, valor):
        if not isinstance(valor, int) or valor <= 0:
            raise ValueError(f"Precio inválido: {valor!r}")
        self._precio = valor

    @property
    def stock(self):              # sin setter: solo lectura
        return self._stock

    @property
    def margen_pct(self):         # calculada: siempre al día
        return round((self.precio - self.costo) * 100 / self.precio, 1)

    def vender(self, cantidad):
        if cantidad <= 0 or cantidad > self._stock:
            raise ValueError("Cantidad inválida")
        self._stock -= cantidad

    def __str__(self):
        return f"{self.nombre} - ₡{self.precio:,} ({self.stock} en bodega)"


