class Carrito:
    def __init__(self, cliente):
        self.cliente = cliente
        self.lineas = {}

    def agregar(self, producto, cantidad):
        if cantidad <= 0:
            raise ValueError("La cantidad debe ser positiva")
        nueva = self.lineas.get(producto, 0) + cantidad
        if nueva > producto.stock:
            raise ValueError(f"Solo hay {producto.stock} de {producto.nombre}")
        self.lineas[producto] = nueva

    @property
    def total(self):
        return sum(p.precio * c for p, c in self.lineas.items())

    @property
    def articulos(self):
        return sum(self.lineas.values())

    def __str__(self):
        filas = [f"Carrito de {self.cliente}"]
        for p, c in self.lineas.items():
            filas.append(f"  {c} x {p.nombre:<28} ₡{p.precio * c:>8,}")
        filas.append(f"  {self.articulos} artículos, total ₡{self.total:,}")
        return "\n".join(filas)


