from datetime import date


class Producto:
    def __init__(self, nombre, precio, stock=0):
        self.nombre = nombre
        self.precio = precio
        self.stock = stock

    def precio_final(self, hoy):
        return self.precio

    def __str__(self):
        return f"{self.nombre} (₡{self.precio:,})"


class ProductoPerecedero(Producto):
    def __init__(self, nombre, precio, vence, stock=0):
        super().__init__(nombre, precio, stock)      # lo común lo hace el padre
        self.vence = date.fromisoformat(vence)

    def dias_para_vencer(self, hoy):
        return (self.vence - hoy).days

    def precio_final(self, hoy):                     # sobrescribe
        if self.dias_para_vencer(hoy) <= 7:
            return round(self.precio * 0.75)         # 25 % de rebaja
        return self.precio

    def __str__(self):                               # extiende
        return f"{super().__str__()} vence {self.vence}"


hoy = date(2026, 9, 30)
productos = [
    Producto("Taza de cerámica pintada", 6000, 85),
    ProductoPerecedero("Chocolate artesanal 70 % cacao", 3500, "2026-10-05", 80),
    ProductoPerecedero("Café molido Orosi 250 g", 3800, "2027-03-01", 95),
]
