import sqlite3
from dataclasses import dataclass

import pytest


@dataclass
class Producto:
    id: int | None
    nombre: str
    categoria_id: int
    precio: int
    costo: int
    stock: int = 0


class ProductoRepositorio:
    def __init__(self, con):
        self.con = con

    def obtener(self, producto_id):
        fila = self.con.execute(
            "SELECT id, nombre, categoria_id, precio, costo, stock FROM productos WHERE id = ?",
            (producto_id,),
        ).fetchone()
        return None if fila is None else Producto(*fila)

    def agregar(self, p):
        with self.con:
            cur = self.con.execute(
                "INSERT INTO productos (nombre, categoria_id, precio, costo, stock) VALUES (?, ?, ?, ?, ?)",
                (p.nombre, p.categoria_id, p.precio, p.costo, p.stock),
            )
        p.id = cur.lastrowid
        return p.id


# ---------- test_repositorio.py ----------
ESQUEMA = """
CREATE TABLE productos (
    id INTEGER PRIMARY KEY,
    nombre TEXT NOT NULL,
    categoria_id INTEGER NOT NULL,
    precio INTEGER NOT NULL CHECK (precio > 0),
    costo INTEGER NOT NULL CHECK (costo > 0),
    stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0)
);
INSERT INTO productos VALUES (1, 'Café molido Tarrazú 500 g', 1, 6500, 3600, 120);
"""


@pytest.fixture
def repo():
    con = sqlite3.connect(":memory:")       # base nueva y vacía para cada prueba
    con.executescript(ESQUEMA)
    yield ProductoRepositorio(con)
    con.close()


def test_obtener_existente(repo):
    assert repo.obtener(1).precio == 6500


def test_obtener_inexistente_devuelve_none(repo):
    assert repo.obtener(999) is None


def test_agregar_asigna_id_y_se_puede_leer(repo):
    nuevo = Producto(None, "Mamita Yunai", 8, 9500, 5700, 12)
    assert repo.agregar(nuevo) == 2
    assert repo.obtener(2) == nuevo


def test_precio_cero_es_rechazado(repo):
    with pytest.raises(sqlite3.IntegrityError):
        repo.agregar(Producto(None, "Regalo", 8, 0, 100))


if __name__ == "__main__":
    pytest.main(["-qq", "-p", "no:cacheprovider", __file__])
